#!/usr/bin/env python3
import argparse
import re
import socket


PROMPT = b"> "
MARKER = b"WIRED_HIDDEN_PARTITION\x00"
XOR_KEY = b"WIRED_SPI"


class SPIProbe:
    def __init__(self, host: str, port: int, timeout: float = 5.0):
        self.sock = socket.create_connection((host, port), timeout=timeout)
        self.sock.settimeout(timeout)
        self._recv_prompt()

    def close(self) -> None:
        try:
            self.command("cs 1")
        except OSError:
            pass
        self.sock.close()

    def _recv_prompt(self) -> str:
        data = b""
        while not data.endswith(PROMPT):
            chunk = self.sock.recv(4096)
            if not chunk:
                raise ConnectionError("probe closed the connection")
            data += chunk
        return data.decode("latin1")

    def command(self, cmd: str) -> str:
        self.sock.sendall(cmd.encode() + b"\n")
        return self._recv_prompt()

    def read64(self, addr: int) -> bytes:
        response = self.command(
            f"tx 03 {addr >> 16:02X} {(addr >> 8) & 0xFF:02X} {addr & 0xFF:02X}"
        )
        hex_bytes = []
        for line in response.splitlines():
            match = re.search(r": ((?:[0-9A-F]{2} ?)+)\s+\|", line)
            if match:
                hex_bytes.extend(match.group(1).split())
        if not hex_bytes:
            raise ValueError(f"could not parse probe response for 0x{addr:06X}: {response!r}")
        return bytes.fromhex("".join(hex_bytes))


def xor_decode(data: bytes, key: bytes) -> bytes:
    return bytes(byte ^ key[index % len(key)] for index, byte in enumerate(data))


def main() -> None:
    parser = argparse.ArgumentParser(description="Solve the Wired SPI Exfil challenge")
    parser.add_argument("--host", default="espilon.net")
    parser.add_argument("--port", type=int, default=37984)
    parser.add_argument(
        "--hidden-offset",
        type=lambda value: int(value, 0),
        default=0x30000,
        help="offset of the unlisted partition (default: 0x30000)",
    )
    args = parser.parse_args()

    probe = SPIProbe(args.host, args.port)
    try:
        probe.command("cs 0")
        partition_table = b"".join(probe.read64(0x8000 + offset) for offset in range(0, 0x100, 0x40))
        hidden_chunk = probe.read64(args.hidden_offset)
    finally:
        probe.close()

    print(partition_table.rstrip(b"\xff").decode("latin1", errors="replace"))

    if not hidden_chunk.startswith(MARKER):
        raise SystemExit(
            f"hidden partition marker not found at 0x{args.hidden_offset:06X}: {hidden_chunk[:32]!r}"
        )

    encoded = hidden_chunk[len(MARKER) :].split(b"\x00", 1)[0]
    flag = xor_decode(encoded, XOR_KEY).decode("ascii")
    print(flag)


if __name__ == "__main__":
    main()

